import math

def build_agent(sandbox):
    # Base fixed to glass at center (x=6.0, y=2.0)
    base = sandbox.add_beam(x=6.0, y=2.0, width=0.05, height=0.05, density=0.01)
    if hasattr(sandbox, 'weld_to_glass'):
        sandbox.weld_to_glass(base, (6.0, 2.0))

    # Create a series of horizontal beams forming a 12m long wiper
    wiper_beams = []
    for i in range(6):
        x = 1.0 + i * 2.0  # Centers at x=1.0, 3.0, ..., 11.0
        beam = sandbox.add_beam(x=x, y=2.0, width=2.0, height=0.05, density=0.01)
        sandbox.set_material_properties(beam, restitution=0.0, friction=0.8)
        wiper_beams.append(beam)

    # Connect wiper beams with rigid joints
    for i in range(5):
        joint = sandbox.add_joint(wiper_beams[i], wiper_beams[i+1], (wiper_beams[i+1].position.x, wiper_beams[i+1].position.y), type='rigid')

    # Pivot joint between base and first wiper beam
    pivot = sandbox.add_joint(
        base, wiper_beams[0], (wiper_beams[0].position.x, wiper_beams[0].position.y), 
        type='pivot', lower_limit=-math.pi, upper_limit=math.pi
    )

    return {"body": base, "motors": [pivot]}

def agent_action(sandbox, agent_body, step_count):
    motors = agent_body.get("motors", []) if isinstance(agent_body, dict) else []
    if not motors:
        return

    # Ensure all bodies are awake
    if hasattr(sandbox, 'set_awake'):
        for body in sandbox.bodies:
            sandbox.set_awake(body, True)

    # Continuous sweeping motion
    motor_speed = 12.0  # Rad/s
    sandbox.set_motor(motors[0], motor_speed, max_torque=28.0)

