    base = sandbox.add_beam(x=6.0, y=2.0, width=0.05, height=0.05, density=0.01)
    if hasattr(sandbox, 'weld_to_glass'):
        sandbox.weld_to_glass(base, (6.0, 2.0))

    # Add six horizontal beams covering the 12m length
    beam_positions = [1.0, 3.0, 5.0, 7.0, 9.0, 11.0]
    motors = []
    for x in beam_positions:
        beam = sandbox.add_beam(x=x, y=2.0, width=2.0, height=0.05, density=0.01)
        sandbox.set_material_properties(beam, restitution=0.0, friction=0.8)
        # Add pivot joint between base and beam
        joint = sandbox.add_joint(
            base, beam, (6.0, 2.0), type='pivot',
            lower_limit=-math.pi, upper_limit=math.pi
        )
        motors.append(joint)

    return {"body": base, "motors": motors}

def agent_action(sandbox, agent_body, step_count):
    motors = agent_body.get("motors", []) if isinstance(agent_body, dict) else []
    if not motors:
        return
    # Ensure all bodies are awake
    if hasattr(sandbox, 'set_awake'):
        for body in sandbox.bodies:
            sandbox.set_awake(body, True)
    # Continuous sweeping motion with controlled speed
    motor_speed = 8.0  # Reduced speed to avoid torque cap
    # Set motor speed with max torque
    for motor in motors:
        sandbox.set_motor(motor, motor_speed, max_torque=28.0)
